The program reads all of stdin as bytes and decodes it as latin1, so string length equals byte count. It then applies the regexes with JavaScript's built-in engine.

- **Original length**: the raw byte count of stdin.
- **Stripping**: one global regex `/>.*\n|\n/g` removes headers and newlines. `.` does not match `\n`, so each header stops at its own line end.
- **Counting**: each of the nine patterns is counted with a global `exec` loop. Matches are never empty, so the loop always advances and counts are non-overlapping.
- **Substitutions**: the five replacements are applied in the given order, then the final length is printed.
- **N**: it is read from `process.argv[2]` per the contract, but this benchmark does not use it.

```typescript
const chunks: Buffer[] = [];
let total = 0;

const N = parseInt(process.argv[2] || "0", 10);
void N;

process.stdin.on("data", (chunk: Buffer) => {
  chunks.push(chunk);
  total += chunk.length;
});

process.stdin.on("end", () => {
  const buf = Buffer.concat(chunks, total);
  const input = buf.toString("latin1");
  const originalLength = buf.length;

  const seq = input.replace(/>.*\n|\n/g, "");
  const strippedLength = seq.length;

  const variants = [
    "agggtaaa|tttaccct",
    "[cgt]gggtaaa|tttaccc[acg]",
    "a[act]ggtaaa|tttacc[agt]t",
    "ag[act]gtaaa|tttac[agt]ct",
    "agg[act]taaa|ttta[agt]cct",
    "aggg[acg]aaa|ttt[cgt]ccct",
    "agggt[cgt]aa|tt[acg]accct",
    "agggta[cgt]a|t[acg]taccct",
    "agggtaa[cgt]|[acg]ttaccct",
  ];

  const out: string[] = [];
  for (const v of variants) {
    const re = new RegExp(v, "g");
    let count = 0;
    while (re.exec(seq) !== null) count++;
    out.push(v + " " + count);
  }

  const subs: [RegExp, string][] = [
    [/tHa[Nt]/g, "<4>"],
    [/aND|caN|Ha[DS]|WaS/g, "<3>"],
    [/a[NSt]|BY/g, "<2>"],
    [/<[^>]*>/g, "|"],
    [/\|[^|][^|]*\|/g, "-"],
  ];

  let s = seq;
  for (const [re, rep] of subs) {
    s = s.replace(re, rep);
  }

  out.push("");
  out.push(String(originalLength));
  out.push(String(strippedLength));
  out.push(String(s.length));
  process.stdout.write(out.join("\n") + "\n");
});

process.stdin.resume();
