function multAv(n: number, v: Float64Array, out: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0;
    // denom(i,j) = (i+j)(i+j+1)/2 + i + 1
    let d = (i * (i + 1)) / 2 + i + 1; // j = 0
    let step = i + 1; // increment from j to j+1: (i+j+1)
    for (let j = 0; j < n; j++) {
      sum += v[j] / d;
      d += step;
      step += 1;
    }
    out[i] = sum;
  }
}

function multAtv(n: number, v: Float64Array, out: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0;
    // A[j][i]: denom(j,i) = (i+j)(i+j+1)/2 + j + 1
    let d = (i * (i + 1)) / 2 + 1; // j = 0
    let step = i + 2; // increment from j to j+1: (i+j+1) + 1
    for (let j = 0; j < n; j++) {
      sum += v[j] / d;
      d += step;
      step += 1;
    }
    out[i] = sum;
  }
}

function multAtAv(n: number, v: Float64Array, out: Float64Array, tmp: Float64Array): void {
  multAv(n, v, tmp);
  multAtv(n, tmp, out);
}

function main(): void {
  const n = parseInt(process.argv[2] || "100", 10);
  const u = new Float64Array(n).fill(1);
  const v = new Float64Array(n);
  const tmp = new Float64Array(n);
  for (let k = 0; k < 10; k++) {
    multAtAv(n, u, v, tmp);
    multAtAv(n, v, u, tmp);
  }
  let vBv = 0, vv = 0;
  for (let i = 0; i < n; i++) {
    vBv += u[i] * v[i];
    vv += v[i] * v[i];
  }
  process.stdout.write(Math.sqrt(vBv / vv).toFixed(9) + "\n");
}

main();
